import * as THREE from 'three/webgpu';
import { texture, uv, vec2 } from 'three/tsl';

export default function createNode(config, ctx) {
  const rectW = 512, rectH = 320, atlasW = 512, atlasH = 320;
  const aspect = rectW / rectH;
  const height = 1.6;
  const width = height * aspect;

  const geometry = new THREE.PlaneGeometry(width, height);
  const material = new THREE.MeshBasicNodeMaterial({ transparent: true });

  const map = ctx.textureLoader.load(config.assets?.imageUrl || '/prism-mock/home/nodes/floating-accent.png');
  map.colorSpace = THREE.SRGBColorSpace;
  map.wrapS = THREE.ClampToEdgeWrapping;
  map.wrapT = THREE.ClampToEdgeWrapping;

  const offsetX = 0 / atlasW;
  const offsetY = 0 / atlasH;
  const scaleX = rectW / atlasW;
  const scaleY = rectH / atlasH;

  const uvNode = uv();
  const atlasUv = uvNode.mul(vec2(scaleX, scaleY)).add(vec2(offsetX, offsetY));
  material.colorNode = texture(map, atlasUv);

  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(0, -0.35, -0.6);
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);

  mesh.userData.handlers = {};

  const onBeforeRender = (renderer, scene, camera) => {
    mesh.quaternion.copy(camera.quaternion);
  };
  mesh.onBeforeRender = onBeforeRender;

  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map) map.dispose();
    mesh.onBeforeRender = () => {};
  };

  return mesh;
}
